<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$supplier=(int)($_POST['supplier_id']??0);$paid=max(0,(float)($_POST['paid']??0));$items=json_decode((string)($_POST['items_json']??'[]'),true);if(!$supplier)throw new RuntimeException('Select a supplier.');if(!is_array($items)||!count($items))throw new RuntimeException('Add at least one medicine.');$clean=[];$total=0;foreach($items as $i=>$row){$mid=(int)($row['medicine_id']??0);$boxes=max(0,(int)($row['boxes']??0));$strips=max(0,(int)($row['strips']??0));$tabs=max(0,(int)($row['tablets']??0));$m=$db->prepare('SELECT * FROM medicines WHERE id=? AND active=1');$m->execute([$mid]);$med=$m->fetch();if(!$med)throw new RuntimeException('Medicine not found on line '.($i+1));$qty=$boxes*(int)$med['strips_per_box']*(int)$med['units_per_strip']+$strips*(int)$med['units_per_strip']+$tabs;if($qty<1)throw new RuntimeException('Enter quantity for '.$med['name']);$cost=max(0,(float)($row['unit_cost']??0));$line=$qty*$cost;$total+=$line;$clean[]=['medicine'=>$med,'boxes'=>$boxes,'strips'=>$strips,'tablets'=>$tabs,'qty'=>$qty,'cost'=>$cost,'total'=>$line,'batch'=>trim((string)($row['batch_no']??'')),'expiry'=>trim((string)($row['expiry_date']??''))];}$paid=min($total,$paid);$db->beginTransaction();$invoice='PUR-'.date('YmdHis').'-'.random_int(10,99);$db->prepare('INSERT INTO purchases(invoice_no,supplier_id,subtotal,paid) VALUES(?,?,?,?)')->execute([$invoice,$supplier,$total,$paid]);$pid=(int)$db->lastInsertId();foreach($clean as $r){$batch=$r['batch']!==''?$r['batch']:'AUTO-'.$invoice.'-'.(int)$r['medicine']['id'];$expiry=$r['expiry']!==''?$r['expiry']:null;$db->prepare('INSERT INTO batches(medicine_id,batch_no,expiry_date,units_received,units_remaining,purchase_unit_cost) VALUES(?,?,?,?,?,?)')->execute([(int)$r['medicine']['id'],$batch,$expiry,$r['qty'],$r['qty'],$r['cost']]);$bid=(int)$db->lastInsertId();$db->prepare('INSERT INTO purchase_items(purchase_id,medicine_id,batch_id,quantity_units,unit_cost,line_total) VALUES(?,?,?,?,?,?)')->execute([$pid,(int)$r['medicine']['id'],$bid,$r['qty'],$r['cost'],$r['total']]);$db->prepare("INSERT INTO stock_movements(medicine_id,batch_id,movement_type,quantity_units,reference_id,note) VALUES(?,?, 'purchase',?,?,?)")->execute([(int)$r['medicine']['id'],$bid,$r['qty'],$pid,'Purchase '.$invoice]);$db->prepare('UPDATE suppliers SET balance=balance+? WHERE id=?')->execute([$r['total'], $supplier]);} $db->prepare('UPDATE suppliers SET balance=balance-? WHERE id=?')->execute([$paid,$supplier]);$db->commit();audit_log('purchase_created','Purchase '.$invoice.' · '.count($clean).' medicines · Rs. '.number_format($total,2));header('Location: purchases.php?saved=1');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}$suppliers=$db->query('SELECT * FROM suppliers ORDER BY name')->fetchAll();$meds=$db->query('SELECT * FROM medicines WHERE active=1 ORDER BY name')->fetchAll();$purchases=$db->query('SELECT p.*,s.name supplier FROM purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id ORDER BY p.id DESC LIMIT 100')->fetchAll(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Purchases · <?=e(APP_NAME)?></title><link rel="stylesheet" href="style.css"><style>html,body{min-height:100%}.purchase-wrap{max-width:1400px;margin:auto}.topline{display:grid;grid-template-columns:1fr 1fr auto;gap:12px;align-items:end;margin-bottom:12px}.topline label{font-size:12px;font-weight:700;color:#475569}.topline select,.topline input{display:block;width:100%;box-sizing:border-box;margin-top:5px;padding:9px;border:1px solid #cbd5e1;border-radius:8px}.table-wrap{overflow:auto}.purchase-table{width:100%;border-collapse:collapse;min-width:1050px}.purchase-table th{background:#f8fafc;color:#475569;font-size:11px;text-align:left;padding:9px;white-space:nowrap}.purchase-table td{padding:6px;border-bottom:1px solid #e2e8f0}.purchase-table input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #cbd5e1;border-radius:6px}.purchase-table .qty{width:70px}.medbox{position:relative}.suggestions{position:absolute;z-index:20;left:0;right:0;top:100%;background:#fff;border:1px solid #cbd5e1;border-radius:8px;box-shadow:0 8px 22px rgba(0,0,0,.12);max-height:250px;overflow:auto}.suggestions button{display:block;width:100%;padding:9px;text-align:left;border:0;border-bottom:1px solid #edf2f7;background:#fff;cursor:pointer}.suggestions button:hover{background:#f1f5f9}.suggestions small{display:block;color:#64748b}.bottom{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-top:12px;flex-wrap:wrap}.totals{display:flex;gap:18px;align-items:center}.grand{font-size:20px;font-weight:800}.paid{display:flex;align-items:center;gap:6px}.paid input{width:130px;padding:9px;border:1px solid #cbd5e1;border-radius:7px}.due{font-size:12px;font-weight:700;color:#9a3412}.history{margin-top:16px}.history table{width:100%}.hint{font-size:11px;color:#64748b}.remove{border:0;background:transparent;color:#dc2626;font-size:20px;cursor:pointer}@media(max-width:850px){.topline{grid-template-columns:1fr}.bottom{align-items:stretch}.totals{flex-wrap:wrap}} </style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav><div class="user-info">👤 <?=e(current_user()['username']??'')?> · <?=e(ucfirst(current_user()['role']??''))?> · <a href="logout.php">Logout</a></div></header><main class="purchase-wrap"><div class="page-title"><div><div class="eyebrow">PURCHASING</div><h1>📦 New Purchase</h1><p>Enter many medicines quickly like an Excel sheet. Batch and expiry are optional.</p></div></div><?php if($error):?><div class="error">✕ <?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ Purchase saved, stock received and supplier balance updated.</div><?php endif;?><section class="panel"><div class="topline"><label>Supplier<select id="supplier" name="supplier_id"><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?> · Balance Rs. <?=money((float)$s['balance'])?></option><?php endforeach;?></select></label><label>Invoice No. <input id="invoicePreview" value="Auto-generated" disabled></label><button type="button" class="btn" id="add">＋ Add Row</button></div><div class="hint">Type a medicine name, select it, then enter Boxes, Strips, Loose tablets and Cost. Batch/Expiry can stay blank.</div><div class="table-wrap" style="margin-top:9px"><table class="purchase-table"><thead><tr><th>#</th><th>Medicine</th><th>Boxes</th><th>Strips</th><th>Loose</th><th>Cost / Tablet</th><th>Batch <small>(optional)</small></th><th>Expiry <small>(optional)</small></th><th>Total Tabs</th><th>Line Total</th><th></th></tr></thead><tbody id="lines"></tbody></table></div><div class="bottom"><button type="button" class="btn" id="add2">＋ Add Another Medicine</button><div class="totals"><span>Medicines: <b id="count">0</b></span><span>Tablets: <b id="tabsTotal">0</b></span><span class="grand">Total: Rs. <span id="grand">0.00</span></span><label class="paid">Paid Now <input id="paid" type="number" min="0" step="0.01" value="0"></label><span class="due" id="due">Due: Rs. 0.00</span><button class="btn" id="save">💾 SAVE PURCHASE</button></div></div></section><section class="panel history"><h2>Recent Purchases</h2><table><tr><th>Invoice</th><th>Supplier</th><th>Total</th><th>Paid</th><th>Due</th><th>Date</th></tr><?php foreach($purchases as $p):?><tr><td><?=e($p['invoice_no'])?></td><td><?=e($p['supplier']??'—')?></td><td>Rs. <?=money((float)$p['subtotal'])?></td><td>Rs. <?=money((float)$p['paid'])?></td><td>Rs. <?=money(max(0,(float)$p['subtotal']-(float)$p['paid']))?></td><td><?=e($p['created_at'])?></td></tr><?php endforeach;?></table></section></main><script>const meds=<?=json_encode($meds,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const lines=document.getElementById('lines');function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}function addRow(){const tr=document.createElement('tr');tr.innerHTML=`<td class="num"></td><td><div class="medbox"><input class="search" placeholder="Type medicine name..." autocomplete="off"><input class="mid" type="hidden"><div class="suggestions" hidden></div></div></td><td><input class="boxes qty" type="number" min="0" value="0"></td><td><input class="strips qty" type="number" min="0" value="0"></td><td><input class="tabs qty" type="number" min="0" value="0"></td><td><input class="cost qty" type="number" min="0" step="0.0001" value="0"></td><td><input class="batch" placeholder="Optional"></td><td><input class="expiry" type="date"></td><td><b class="rowtabs">0</b></td><td><b>Rs. <span class="linetotal">0.00</span></b></td><td><button type="button" class="remove">×</button></td>`;lines.appendChild(tr);const search=tr.querySelector('.search'),sug=tr.querySelector('.suggestions');function show(){const q=search.value.toLowerCase().trim();const found=(q?meds.filter(m=>(m.name+' '+(m.generic_name||'')+' '+(m.strength||'')+' '+(m.barcode||'')).toLowerCase().includes(q)):meds).slice(0,30);sug.innerHTML=found.map(m=>`<button type="button" data-id="${m.id}"><b>${esc(m.name)}</b><small>${esc((m.generic_name||'')+' '+(m.strength||''))} · ${m.units_per_strip}/strip · ${m.strips_per_box}/box</small></button>`).join('')||'<div style="padding:9px">No medicine found</div>';sug.hidden=false;sug.querySelectorAll('button').forEach(b=>b.onclick=()=>select(meds.find(m=>m.id==b.dataset.id)));}function select(m){tr.querySelector('.mid').value=m.id;search.value=m.name;tr.querySelector('.cost').value=Number(m.purchase_price||0).toFixed(4);sug.hidden=true;tr.querySelector('.boxes').focus();calc();}search.addEventListener('input',show);search.addEventListener('focus',show);search.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const b=sug.querySelector('button');if(b)b.click()}});tr.querySelectorAll('input').forEach(x=>x.addEventListener('input',calc));tr.querySelector('.remove').onclick=()=>{tr.remove();if(!lines.children.length)addRow();calc()};calc();}function calc(){let total=0,tabs=0;[...lines.children].forEach((tr,i)=>{tr.querySelector('.num').textContent=i+1;const m=meds.find(x=>Number(x.id)===Number(tr.querySelector('.mid').value));const b=+tr.querySelector('.boxes').value||0,s=+tr.querySelector('.strips').value||0,t=+tr.querySelector('.tabs').value||0,c=+tr.querySelector('.cost').value||0;const q=m?b*Number(m.strips_per_box)*Number(m.units_per_strip)+s*Number(m.units_per_strip)+t:0;tabs+=q;total+=q*c;tr.querySelector('.rowtabs').textContent=q.toLocaleString();tr.querySelector('.linetotal').textContent=(q*c).toFixed(2)});document.getElementById('count').textContent=lines.children.length;document.getElementById('tabsTotal').textContent=tabs.toLocaleString();document.getElementById('grand').textContent=total.toFixed(2);const p=+document.getElementById('paid').value||0;document.getElementById('due').textContent='Due: Rs. '+Math.max(0,total-p).toFixed(2);}document.getElementById('add').onclick=()=>addRow();document.getElementById('add2').onclick=()=>addRow();document.getElementById('paid').addEventListener('input',calc);document.getElementById('save').onclick=()=>{const supplier=+document.getElementById('supplier').value||0;if(!supplier)return alert('Select a supplier.');const data=[];for(const tr of lines.children){const mid=+tr.querySelector('.mid').value||0;if(!mid){alert('Select a medicine on row '+(data.length+1)+'.');tr.querySelector('.search').focus();return}const m=meds.find(x=>+x.id===mid),b=+tr.querySelector('.boxes').value||0,s=+tr.querySelector('.strips').value||0,t=+tr.querySelector('.tabs').value||0,q=b*m.strips_per_box*m.units_per_strip+s*m.units_per_strip+t;if(q<1){alert('Enter quantity for '+m.name+'.');return}data.push({medicine_id:mid,boxes:b,strips:s,tablets:t,unit_cost:+tr.querySelector('.cost').value||0,batch_no:tr.querySelector('.batch').value,expiry_date:tr.querySelector('.expiry').value})}const f=document.createElement('form');f.method='post';f.action='purchases.php';f.innerHTML='<input name="supplier_id"><input name="paid"><input name="items_json">';f.querySelector('[name=supplier_id]').value=supplier;f.querySelector('[name=paid]').value=document.getElementById('paid').value||0;f.querySelector('[name=items_json]').value=JSON.stringify(data);document.body.appendChild(f);f.submit()};document.addEventListener('click',e=>{if(!e.target.closest('.medbox'))document.querySelectorAll('.suggestions').forEach(x=>x.hidden=true)});document.addEventListener('keydown',e=>{if(e.key==='F2'){e.preventDefault();addRow()}if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();document.getElementById('save').click()}});addRow();addRow();</script></body></html>